### Example code

```go
package main

import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/app"
	"fyne.io/fyne/v2/container"
	"fyne.io/fyne/v2/theme"
	"fyne.io/fyne/v2/widget"
)

type Option int

const (
	UseOnlySetColumnWidth Option = iota
	UseOnlySetRowHeight
	UseSetColumnWidthAndSetRowHeight
	NoSetColumnWidthAndSetRowHeight
)

var (
	columnMinWidth []float32
	rowMinHeight   []float32
)

func NewTable(option Option) *widget.Table {
	rows, cols := 10, 10

	table := widget.NewTable(
		func() (int, int) { return rows, cols },
		func() fyne.CanvasObject { return widget.NewLabel("") },
		nil,
	)

	table.ShowHeaderRow = true
	table.ShowHeaderColumn = true
	table.HideSeparators = true

	table.UpdateCell = func(id widget.TableCellID, o fyne.CanvasObject) {
		updateCell(table, option, id, o)
	}

	columnMinWidth = make([]float32, cols)
	rowMinHeight = make([]float32, rows)
	return table
}

func updateCell(t *widget.Table, option Option, id widget.TableCellID, o fyne.CanvasObject) {
	o.(*widget.Label).SetText(fmt.Sprintf("%d, %d", id.Row, id.Col))

	if option == NoSetColumnWidthAndSetRowHeight {
		return
	}

	minSize := o.(*widget.Label).MinSize()

	if option == UseOnlySetColumnWidth || option == UseSetColumnWidthAndSetRowHeight {
		if minSize.Width > columnMinWidth[id.Col] {
			columnMinWidth[id.Col] = minSize.Width
			t.SetColumnWidth(id.Col, columnMinWidth[id.Col])
		}
	}

	if option == UseOnlySetRowHeight || option == UseSetColumnWidthAndSetRowHeight {
		if minSize.Height > rowMinHeight[id.Row] {
			rowMinHeight[id.Row] = minSize.Height + 5
			t.SetRowHeight(id.Row, rowMinHeight[id.Row])
		}
	}
}

func main() {
	myApp := app.New()
	w := myApp.NewWindow("Table Bug: Headers Vanish")
	w.Resize(fyne.NewSize(800, 400))

	contentArea := container.NewStack(widget.NewLabel("No Table"))

	split := container.NewHSplit(
		container.NewVBox(
			widget.NewButtonWithIcon("Load Table (UseOnlySetColumnWidth)", theme.NewErrorThemedResource(theme.ErrorIcon()), func() {
				contentArea.Objects = []fyne.CanvasObject{NewTable(UseOnlySetColumnWidth)}
				contentArea.Refresh()
			}),
			widget.NewButtonWithIcon("Load Table (UseOnlySetRowHeight)", theme.NewErrorThemedResource(theme.ErrorIcon()), func() {
				contentArea.Objects = []fyne.CanvasObject{NewTable(UseOnlySetRowHeight)}
				contentArea.Refresh()
			}),
			widget.NewButtonWithIcon("Load Table (UseSetColumnWidthAndSetRowHeight)", theme.NewErrorThemedResource(theme.ErrorIcon()), func() {
				contentArea.Objects = []fyne.CanvasObject{NewTable(UseSetColumnWidthAndSetRowHeight)}
				contentArea.Refresh()
			}),
			widget.NewButtonWithIcon("Load Table (NoSetColumnWidthAndSetRowHeight)", theme.NewSuccessThemedResource(theme.ConfirmIcon()), func() {
				contentArea.Objects = []fyne.CanvasObject{NewTable(NoSetColumnWidthAndSetRowHeight)}
				contentArea.Refresh()
			}),
		),
		contentArea,
	)

	w.SetContent(split)
	w.ShowAndRun()
}

