I'd like to report some question I asked on slack: https://gophers.slack.com/archives/CB4QUBXGQ/p1658235311531199

The question was related to a difficulty testing fyne when using bindings.

One of the nice people there pointed me to some of the fyne unit tests and I came up with a testing pattern:

```golang
package main

import (
	"testing"
	"time"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/data/binding"
	"fyne.io/fyne/v2/test"
	"fyne.io/fyne/v2/widget"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func bindingShouldEqual(t *testing.T, b binding.String, exp string) {
	v, err := b.Get()
	require.NoError(t, err)
	assert.Equal(t, exp, v)
}

func waitOnChan(t *testing.T, propagated chan bool) {
	select {
	case <-propagated:
	case <-time.After(1 * time.Second):
		assert.Fail(t, "The test should not have timedout")
	}
}

func NewListener(data binding.DataItem) chan bool {
	propagated := make(chan bool)
	listener := binding.NewDataListener(func() {
		go func() {
			propagated <- true
		}()
	})
	data.AddListener(listener)
	<-propagated // ignore init callback

	return propagated
}

// typeWithBindingChan types each character individually waiting on the binding
// chan between each character to ensure safety
// NOTE: if you try to use test.Type() directly on you fyne.Focusable this does not
// work as intended
func typeWithBindingChan(t *testing.T, obj fyne.Focusable, chars string, propagated chan bool) {
	for _, char := range chars {
		test.Type(obj, string(char))
		waitOnChan(t, propagated)
	}
}

func makeFyneUI(bind binding.String) (*widget.Label, *widget.Entry) {
	hello := widget.NewLabelWithData(bind)
	entry := widget.NewEntryWithData(bind)
	return hello, entry
}

func TestGreeting(t *testing.T) {
	bind := binding.NewString()
	_, entry := makeFyneUI(bind)

	bindingShouldEqual(t, bind, "")

	propagatedString := NewListener(bind)

	typeWithBindingChan(t, entry, "12345678901234567890", propagatedString)

	bindingShouldEqual(t, bind, "12345678901234567890")
}
```

Further discussion lead to the idea that it could be nice to add this bit of information in the documentation at the end of the binding chapter.

Best regard,
